CREATE TABLE `job_category` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL COMMENT '分类名称',
  `parent_id` int DEFAULT NULL COMMENT '父级ID，NULL=一级行业',
  `sort_order` int DEFAULT '0' COMMENT '排序',
